<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $venta->numero }}</title><style>body{font:13px Arial;background:#eee;color:#111}.receipt{max-width:{{ $impresora?->papel_mm ?: 80 }}mm;background:white;margin:20px auto;padding:6mm}.receipt h1{text-align:center;font-size:18px}.receipt dl{display:grid;grid-template-columns:1fr auto;gap:6px}.receipt dd{margin:0;text-align:right}.receipt .total{font-weight:bold;border-top:1px dashed;padding-top:7px}.actions{text-align:center}@media print{@page{size:{{ ($impresora?->papel_mm ?: 80)===210?'A4':($impresora?->papel_mm ?: 80).'mm auto' }};margin:3mm}body{background:white}.receipt{max-width:100%;margin:0;padding:2mm}.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Imprimir</button></div><main class="receipt"><h1>{{ \App\Models\ConfiguracionPago::actual()->razon_social ?: 'Parke’o' }}</h1><p style="text-align:center">{{ ucfirst($venta->tipo_comprobante) }} · {{ $venta->numero }}<br>{{ $venta->fecha?->format('d/m/Y H:i') }}</p>@if($venta->estado==='anulada')<p style="text-align:center;font-weight:bold">ANULADA</p>@endif<dl><dt>Cliente</dt><dd>{{ $venta->cliente }}</dd>@if($venta->documento)<dt>Documento</dt><dd>{{ $venta->documento }}</dd>@endif<dt>Servicio</dt><dd>{{ $venta->concepto }}</dd><dt>Importe</dt><dd>S/ {{ number_format($venta->importe_base,2) }}</dd>@if($venta->descuento>0)<dt>Descuento</dt><dd>− S/ {{ number_format($venta->descuento,2) }}</dd>@endif<dt class="total">Total</dt><dd class="total">S/ {{ number_format($venta->total,2) }}</dd>@foreach($venta->pagos->whereIn('estado',$venta->estado==='anulada'?['cancelado']:['aprobado','reembolsado']) as $pago)<dt>{{ ucfirst($pago->metodo_pago) }}</dt><dd>S/ {{ number_format($pago->monto,2) }}</dd>@endforeach</dl></main><script>window.addEventListener('load',()=>window.print())</script></body></html>
